def normalize_peak(samples, peak=1.0):
    if peak < 0:
        raise ValueError('peak must be non-negative')
    values = list(samples)
    maximum = max((abs(x) for x in values), default=0)
    if maximum == 0:
        return values
    scale = peak / maximum
    return [x * scale for x in values]

import math

def rms(samples):
    values = list(samples)
    if not values:
        return 0.0
    return math.sqrt(sum(value * value for value in values) / len(values))

def linear_crossfade(a, b):
    if len(a) != len(b):
        raise ValueError('sequences must have equal length')
    n = len(a)
    if n == 0:
        return []
    if n == 1:
        return [b[0]]
    return [a[i] * (1 - i / (n - 1)) + b[i] * (i / (n - 1)) for i in range(n)]
